_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]
_CHILD_ENV = {"PATH": "/usr/local/bin:/usr/bin:/bin", "PYTHONHASHSEED": "0", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"}
_MODULE_TIMEOUT = 120
_LOCK = threading.RLock()
_GRADE_LOCK = threading.Lock()
_MEMO: dict[str, Any] = {}
_AUDIT: list[dict[str, Any]] = []

# The submission runs inside this program. The audit hook is installed before the
# submission is loaded and writes one JSON line per event to an inherited pipe.
_RUNNER = r'''
import json, os, sys
fd = int(sys.argv[1])
module_path, mode = sys.argv[2], sys.argv[3]
args = sys.argv[4:]
stdlib = set(sys.stdlib_module_names)
watched = {"open", "os.listdir", "os.scandir", "os.remove", "os.rename", "os.mkdir", "shutil.rmtree",
           "socket.connect", "socket.getaddrinfo", "socket.bind", "subprocess.Popen", "os.system", "os.exec"}
def hook(event, payload):
    try:
        if event == "import":
            top = str(payload[0]).split(".")[0]
            if top and top not in stdlib and top != "submitted_optimize":
                os.write(fd, (json.dumps(["import", top, ""]) + "\n").encode())
        elif event in watched:
            first = payload[0] if payload else ""
            mode_ = payload[1] if event == "open" and len(payload) > 1 else ""
            os.write(fd, (json.dumps([event, os.fsdecode(first) if isinstance(first, (str, bytes)) else str(first), str(mode_)]) + "\n").encode())
    except Exception:
        pass
sys.addaudithook(hook)
import importlib.util
spec = importlib.util.spec_from_file_location("submitted_optimize", module_path)
module = importlib.util.module_from_spec(spec)
if mode == "call":
    spec.loader.exec_module(module)
    result = module.aggregate(args[0], args[1])
    sys.stdout.write(json.dumps(result, sort_keys=True))
else:
    import runpy
    sys.argv = [module_path] + args
    runpy.run_path(module_path, run_name="__main__")
'''

_BASELINE = r'''
import sys
namespace = {"__name__": "baseline"}
exec(compile(open(sys.argv[1], encoding="utf-8").read(), "baseline", "exec"), namespace)
namespace["rewalk"](sys.argv[2], sys.argv[3])
'''


# --------------------------------------------------------------------------
# small helpers
# --------------------------------------------------------------------------


def _memo(key: str, build):
    with _LOCK:
        if key not in _MEMO:
            _MEMO[key] = build()
        return _MEMO[key]


def _read_json(path: Path) -> Any:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _same(left: Any, right: Any) -> bool:
    """Exact equality that also tells 5 from 5.0 and 1 from true."""
    return json.dumps(left, sort_keys=True) == json.dumps(right, sort_keys=True)


def _holds(check) -> bool:
    with _GRADE_LOCK:
        try:
            return bool(check())
        except Exception:
            return False


def _scratch(tag: str) -> Path:
    path = Path(tempfile.mkdtemp(prefix=f"rating-{tag}-"))
    path.chmod(0o755)
    return path


def _unpack(blobs: dict[str, str], tag: str) -> Path:
    root = _scratch(tag)
    for rel, blob in blobs.items():
        target = root / rel
        target.write_bytes(zlib.decompress(base64.b64decode(blob)))
        target.chmod(0o644)
    return root


def _data_dir() -> Path:
    """The agent's extract, rebuilt here from the embedded copy."""
    return _memo("data_dir", lambda: _unpack(_SHIPPED_DATA, "shipped"))


def extract(name: str) -> tuple[Path, Path]:
    """One of the other extracts, rebuilt at a fresh path."""
    def build() -> tuple[Path, Path]:
        events, rules, blobs = _EXTRACTS[name]
        root = _unpack(blobs, f"x-{name}")
        return root / events, root / rules
    return _memo(f"extract:{name}", build)


# --------------------------------------------------------------------------
# reference
# --------------------------------------------------------------------------


def ref_csv(path):
    return list(csv.DictReader(io.StringIO(open(path, encoding="utf-8").read())))


def ref_reduce(kinds, card, figures):
    """Row-reduce the batch equations: (free kinds, [(pivot kind, constant, {free: coefficient})])."""
    names = sorted(figures)
    matrix = [[Fraction(0)] * len(kinds) + [Fraction(int(figures[n]))] for n in names]
    for line in card:
        matrix[names.index(line["batch"])][kinds.index(line["kind"])] += int(line["amount"]) * int(line["units"])
    pivots = []
    for col in range(len(kinds)):
        r = len(pivots)
        hit = [i for i in range(r, len(matrix)) if matrix[i][col] != 0]
        if not hit:
            continue
        matrix[r], matrix[hit[0]] = matrix[hit[0]], matrix[r]
        lead = matrix[r][col]
        matrix[r] = [x / lead for x in matrix[r]]
        for i in range(len(matrix)):
            if i != r and matrix[i][col] != 0:
                f = matrix[i][col]
                matrix[i] = [a - f * b for a, b in zip(matrix[i], matrix[r])]
        pivots.append(col)
    if any(row[-1] != 0 and not any(row[:-1]) for row in matrix):
        return None
    free = [c for c in range(len(kinds)) if c not in pivots]
    return free, [(col, matrix[i][-1], {f: matrix[i][f] for f in free if matrix[i][f] != 0}) for i, col in enumerate(pivots)]


def ref_journal(path, extra=()):
    """Journal lines grouped by account, each account in processing order (ts, id number)."""
    accounts = {}
    for line in ref_csv(path):
        row = {"kind": line["kind"], "amount": int(line["amount"]), "units": int(line["units"]), "flag": line["flag"],
               "ts": int(line["ts"]), "num": int(line["row"][1:])}
        for key in extra:
            row[key] = line[key]
        accounts.setdefault(line["account"], []).append(row)
    for rows in accounts.values():
        rows.sort(key=lambda r: (r["ts"], r["num"]))
        for p, r in enumerate(rows):
            r["pos"] = p
    return accounts


def ref_candidates(kinds, card, figures, journal, lo=2, hi=40, cap=64):
    """Every (weights, table, complete) reproducing the figures and the withdrawal journal.
    Free weights are fixed one at a time; each journal account is replayed once every kind
    among its ordinary rows has a weight, extending one shared table with backtracking."""
    reduced = ref_reduce(kinds, card, figures)
    if reduced is None:
        return []
    free, pivots = reduced
    accounts = sorted(journal.values(), key=lambda rows: (len({r["kind"] for r in rows}), len(rows)))
    uses = [frozenset(kinds.index(r["kind"]) for r in rows if r["flag"] not in CONTROL) for rows in accounts]
    fixed_cols = {c for c, _, co in pivots if not co}
    plan, pending, chosen = [], set(range(len(accounts))), []
    known = set(fixed_cols)
    start = [i for i in sorted(pending) if len(uses[i]) <= 1 or uses[i] <= known]
    pending -= set(start)
    rest = list(free)
    while rest:
        scores = []
        for f in rest:
            trial = set(chosen) | {f}
            reach = known | {f} | {c for c, _, co in pivots if co and set(co) <= trial}
            scores.append((sum(1 for i in pending if uses[i] <= reach), -rest.index(f), f))
        f = max(scores)[2]
        rest.remove(f)
        chosen.append(f)
        newly = [p for p in pivots if p[2] and set(p[2]) <= set(chosen) and p[0] not in known]
        known |= {f} | {p[0] for p in newly}
        ready = sorted(i for i in pending if uses[i] <= known)
        pending -= set(ready)
        plan.append((f, newly, ready))
    value = {}
    table = {}
    out = []
    pairs = [(a, b) for a in kinds for b in kinds if a != b]

    def weights():
        return {k: value.get(j, 1) for j, k in enumerate(kinds)}

    def fill(group):
        for col, rhs, co in group:
            v = rhs - sum(c * value[f] for f, c in co.items())
            if v.denominator != 1 or v < lo or v > hi:
                return False
            value[col] = int(v)
        return True

    def through(ids, k, then):
        if len(out) >= cap:
            return
        if k == len(ids):
            then()
            return
        for option in ref_account_options(accounts[ids[k]], table, weights()):
            table.update(option)
            through(ids, k + 1, then)
            for key in option:
                del table[key]

    def level(d):
        if d == len(plan):
            out.append(({k: value[j] for j, k in enumerate(kinds)}, dict(table), all(p in table for p in pairs)))
            return
        f, group, ready = plan[d]
        for v in range(lo, hi + 1):
            value[f] = v
            if fill(group):
                through(ready, 0, lambda: level(d + 1))
            for col, _, _ in group:
                value.pop(col, None)
            if len(out) >= cap:
                break
        value.pop(f, None)

    if fill([p for p in pivots if not p[2]]):
        through(start, 0, lambda: level(0))
    return out


def ref_preference(row, void_kind, weights):
    charge = row["amount"] * row["units"] * weights[row["kind"]]
    if row["kind"] == void_kind:
        return (0, -charge, -row["pos"])
    return (1, charge, row["pos"])


def ref_account_options(rows, fixed, weights):
    """Every set of new table entries under which one journal account replays exactly."""
    options = []

    def go(j, live, stack, new):
        if j == len(rows):
            alive = set(live)
            if all(r["state"] == ("live" if r["pos"] in alive else "withdrawn") for r in rows if r["flag"] not in CONTROL):
                options.append(dict(new))
            return
        r = rows[j]
        if r["flag"] == "revive":
            if stack and r["state"] == "applied":
                go(j + 1, live + [stack[-1]], stack[:-1], new)
            if not stack and r["state"] == "orphan":
                go(j + 1, live, stack, new)
            return
        if r["flag"] != "void":
            go(j + 1, live + [r["pos"]], stack, new)
            return
        ranked = sorted(live, key=lambda p: ref_preference(rows[p], r["kind"], weights))

        def scan(c):
            if c == len(ranked):
                if r["state"] == "orphan":
                    go(j + 1, live, stack, new)
                return
            p = ranked[c]
            pair = (r["kind"], rows[p]["kind"])
            allowed = True if pair[0] == pair[1] else fixed.get(pair, new.get(pair))
            if allowed is None:
                for value in (True, False):
                    new[pair] = value
                    scan(c)
                del new[pair]
            elif allowed:
                if r["state"] == "applied":
                    go(j + 1, [x for x in live if x != p], stack + [p], new)
            else:
                scan(c + 1)

        scan(0)

    go(0, [], [], {})
    return options


def ref_period_premium(period, rules, weights, table):
    """Standing in a journal period: no carry, floor 2000, the legacy rules."""
    quantum = int(rules["latency_quantum"])
    plain, room, count, sponsor = {}, {}, {}, {}
    for name, rows in period.items():
        holding, stack = [], []
        for r in rows:
            if r["flag"] == "void":
                allowed = [p for p in holding if rows[p]["kind"] == r["kind"] or table[(r["kind"], rows[p]["kind"])]]
                if allowed:
                    gone = min(allowed, key=lambda p: ref_preference(rows[p], r["kind"], weights))
                    holding.remove(gone)
                    stack.append(gone)
            elif r["flag"] == "revive":
                if stack:
                    holding.append(stack.pop())
            else:
                holding.append(r["pos"])
        count[name] = sum(1 for r in rows if r["flag"] not in CONTROL)
        plain[name] = room[name] = 0
        for p in holding:
            r = rows[p]
            pen = int(rules["flag_penalties"].get(r["flag"], 0))
            plain[name] += (r["amount"] * r["units"] * int(weights[r["kind"]]) + int(rules["region_offsets"][r["region"]])
                            - int(r["latency_ms"]) // quantum) - pen
            room[name] += pen
        sponsor[name] = rows[0]["sponsor"]
    premium = set()
    while True:
        grown = {m for m in period if count[m] > 0 and plain[m] + (room[m] if sponsor[m] in premium else 0) >= 2000 * count[m]}
        if grown == premium:
            return premium
        premium = grown


def ref_configuration(folder, rules):
    kinds = list(rules["kinds"])
    journal = ref_journal(folder / rules["withdrawals_journal_file"], ("state",))
    found = ref_candidates(kinds, ref_csv(folder / rules["rate_card_file"]), json.loads(
        open(folder / rules["rate_figures_file"], encoding="utf-8").read())["figures"], journal)
    period = ref_journal(folder / rules["standing_journal_file"], ("sponsor", "region", "latency_ms", "standing"))
    recorded = {m for m, rows in period.items() if rows[0]["standing"] == "premium"}
    settled = [(w, t) for w, t, complete in found if complete and ref_period_premium(period, rules, w, t) == recorded]
    if len(settled) != 1 or any(not c for _, _, c in found):
        raise ValueError("the evidence does not settle one configuration")
    return settled[0]


def ref_resolve(moves, name, stamp):
    for _ in range(len(moves) + 2):
        recs = [r for r in moves.get(name, ()) if r[0] < stamp]
        if not recs or not recs[-1][1]:
            return name
        name = recs[-1][1]
    return name


def ref_rate(events_path, rules_path, config=None):
    events_path, rules_path = Path(events_path), Path(rules_path)
    folder = rules_path.parent
    rules = json.loads(open(rules_path, encoding="utf-8").read())
    weights, table = config if config is not None else ref_configuration(folder, rules)
    best = {}
    for idx, line in enumerate(ref_csv(folder / rules["registry_file"])):
        rank = (line["updated"], idx)
        if line["account"] not in best or best[line["account"]][0] <= rank:
            best[line["account"]] = (rank, line)
    record = {name: line for name, (_, line) in best.items()}
    for line in json.loads(open(folder / rules["export_file"], encoding="utf-8").read())["accounts"]:
        if line["account"] not in record:
            record[line["account"]] = line
    moves = {}
    for line in ref_csv(folder / rules["merges_file"]):
        moves.setdefault(line["account"], []).append((int(line["effective_ts"]), line["merged_into"]))
    moves = {k: sorted(v) for k, v in moves.items()}
    entries = [json.loads(t) for t in open(folder / rules["errata_file"], encoding="utf-8").read().splitlines() if t.strip()]
    dead = {e["reverts"] for e in entries if "reverts" in e}
    chosen = {}
    for e in entries:
        if "reverts" in e or e["erratum"] in dead:
            continue
        key = (e["booked_account"], int(e["ts"]), e["field"])
        num = int(e["erratum"][3:])
        if key not in chosen or num < chosen[key][0]:
            chosen[key] = (num, str(e["value"]))
    fixes = {}
    for (acct, ts, field), (_, value) in chosen.items():
        fixes.setdefault((acct, ts), {})[field] = value
    text = open(events_path, encoding="utf-8-sig").read()
    reader = csv.DictReader(io.StringIO(text))
    micro = "latency_us" in (reader.fieldnames or [])
    table_rows = []
    for cells in reader:
        cells["account"] = cells["account"].strip().upper()
        cells["kind"] = cells["kind"].strip().lower()
        cells["flag"] = cells["flag"].strip().lower()
        table_rows.append(cells)
    unpriced = unregistered = rebooked = 0
    rows = []
    for cells in table_rows:
        ts = int(cells["ts"])
        owner = ref_resolve(moves, cells["account"], ts)
        if owner not in record:
            unregistered += 1
            continue
        fix = fixes.get((owner, ts), {})
        amount = fix.get("amount", cells["amount"])
        if amount == "":
            unpriced += 1
            continue
        rebooked += owner != cells["account"]
        lat = int(cells["latency_us"]) if micro else int(cells["latency_ms"])
        if micro:
            lat = (lat + 500) // 1000
        flag = fix.get("flag", cells["flag"])
        zero = flag in CONTROL
        rows.append({"ts": ts, "num": int(cells["id"][1:]), "id": cells["id"], "owner": owner, "kind": cells["kind"],
                     "amount": 0 if zero else int(amount), "units": 0 if zero else int(fix.get("units", cells["units"])),
                     "lat": lat, "flag": flag, "fixed": (owner, ts) in fixes})
    rows.sort(key=lambda r: (r["ts"], r["num"]))
    modulus, quantum = int(rules["carry_modulus"]), int(rules["latency_quantum"])
    carry = {}
    holding = {}
    taken = {}
    live = set()
    orphan_voids = orphan_revives = 0
    for pos, r in enumerate(rows):
        r["pos"] = pos
        r["region"] = record[r["owner"]]["home_region"]
        r["ctl"] = r["flag"] in CONTROL
        base = r["amount"] * r["units"] * int(weights[r["kind"]]) + int(rules["region_offsets"][r["region"]]) - r["lat"] // quantum
        r["pen"] = int(rules["flag_penalties"].get(r["flag"], 0))
        if r["ctl"]:
            r["carried"] = base
            if r["flag"] == "void":
                pool = holding.get(r["owner"], [])
                allowed = [p for p in pool if rows[p]["kind"] == r["kind"] or table.get((r["kind"], rows[p]["kind"]))]
                if allowed:
                    gone = min(allowed, key=lambda p: ref_preference(rows[p], r["kind"], weights))
                    pool.remove(gone)
                    live.discard(gone)
                    taken.setdefault(r["owner"], []).append(gone)
                else:
                    orphan_voids += 1
            else:
                stack = taken.get(r["owner"], [])
                if stack:
                    back = stack.pop()
                    live.add(back)
                    holding.setdefault(r["owner"], []).append(back)
                else:
                    orphan_revives += 1
            continue
        r["carried"] = base + carry.get(r["region"], 0)
        carry[r["region"]] = r["carried"] % modulus
        holding.setdefault(r["owner"], []).append(pos)
        live.add(pos)
    members = sorted({r["owner"] for r in rows if not r["ctl"]})
    plain = dict.fromkeys(members, 0)
    room = dict.fromkeys(members, 0)
    count = dict.fromkeys(members, 0)
    for r in rows:
        if r["ctl"]:
            continue
        count[r["owner"]] += 1
        if r["pos"] in live:
            plain[r["owner"]] += r["carried"] - r["pen"]
            room[r["owner"]] += r["pen"]
    sponsor = {}
    for m in members:
        named = record[m].get("sponsor") or ""
        sponsor[m] = ref_resolve(moves, named, float("inf")) if named else ""
    floor = int(rules["premium_floor"])
    premium = set()
    while True:
        grown = {m for m in members if plain[m] + (room[m] if sponsor[m] in premium else 0) >= floor * count[m]}
        if grown == premium:
            break
        premium = grown
    fold = 0
    waived = cancelled = 0
    amended = []
    accounts = dict.fromkeys(members, 0)
    regions, kinds, flags = {}, {}, {}
    for r in rows:
        free = (not r["ctl"]) and sponsor.get(r["owner"], "") in premium
        final = r["carried"] - (0 if free else r["pen"])
        waived += r["pen"] if free else 0
        fold = (fold * FOLD_MULTIPLIER + final * (r["pos"] + 1) + r["num"]) & FOLD_MASK
        if r["fixed"]:
            amended.append([r["id"], final])
        if r["ctl"]:
            flags[r["flag"]] = flags.get(r["flag"], 0) + 1
            continue
        on = r["pos"] in live
        accounts[r["owner"]] += final if on else 0
        regions[r["region"]] = regions.get(r["region"], 0) + (final if on else 0)
        kinds[r["kind"]] = kinds.get(r["kind"], 0) + (final if on else 0)
        flags[r["flag"]] = flags.get(r["flag"], 0) + (1 if on else 0)
        cancelled += 0 if on else final
    leaders = sorted(accounts, key=lambda n: (-accounts[n], n))[: int(rules["top_n"])]
    result = {
        "label": str(rules["label"]),
        "event_count": len(table_rows),
        "account_totals": {k: accounts[k] for k in sorted(accounts)},
        "region_totals": {k: regions[k] for k in sorted(regions)},
        "kind_totals": {k: kinds[k] for k in sorted(kinds)},
        "flag_counts": {k: flags[k] for k in sorted(flags)},
        "premium_accounts": sorted(premium),
        "top_accounts": [[n, accounts[n]] for n in leaders],
        "checksum": fold,
    }
    quality = {"unpriced_rows": unpriced, "unregistered_rows": unregistered, "rebooked_rows": rebooked,
               "orphan_voids": orphan_voids, "orphan_revives": orphan_revives, "cancelled_score": cancelled,
               "amendments": amended}
    nlive = sum(1 for r in rows if not r["ctl"] and r["pos"] in live)
    return {"result": result, "quality": quality,
            "rescued": sorted(m for m in premium if plain[m] < floor * count[m]), "waived": waived,
            "processed": len(rows), "live": nlive, "config": (weights, table)}


def rewalk(events_path, rules_path):
    """The slow shape the task starts from: redo every step once per group key."""
    shape = ref_rate(events_path, rules_path)["result"]
    out = dict(shape)
    for group in GROUPS:
        out[group] = {key: ref_rate(events_path, rules_path)["result"][group][key] for key in shape[group]}
    return out


def _baseline_source() -> Path:
    def build() -> Path:
        head = ("import csv, io, json, sys\nsys.setrecursionlimit(20000)\nfrom fractions import Fraction\nfrom itertools import product\n"
                "from pathlib import Path\nFOLD_MULTIPLIER = 1315423911\nFOLD_MASK = 0xFFFFFFFF\n"
                "CONTROL = ('void', 'revive')\nGROUPS = ('account_totals', 'region_totals', 'kind_totals', 'flag_counts')\n\n")
        body = "\n\n".join(inspect.getsource(fn) for fn in (ref_csv, ref_reduce, ref_journal, ref_candidates, ref_preference,
                                                            ref_account_options, ref_period_premium, ref_configuration,
                                                            ref_resolve, ref_rate, rewalk))
        path = _scratch("baseline") / "baseline_engine.py"
        path.write_text(head + body, encoding="utf-8")
        # Only the verifier (root) runs the baseline; submitted code never reads it.
        path.parent.chmod(0o700)
        path.chmod(0o600)
        return path
    return _memo("baseline_source", build)


def expected_reports() -> dict[str, Any]:
    def build() -> dict[str, Any]:
        data = _data_dir()
        manifest = _read_json(data / "manifest.json")
        rules = data / manifest["rules"]
        files: dict[str, Any] = {}
        quality, advice, load = [], [], []
        processed = 0
        config = None
        for entry in manifest["scenarios"]:
            run = ref_rate(data / entry["source"], rules, config)
            config = run["config"]
            res = run["result"]
            total = sum(res["account_totals"].values())
            head = res["top_accounts"][0] if res["top_accounts"] else [None, 0]
            files[f"scenario_{entry['name']}.json"] = {
                "scenario": entry["name"], "source": entry["source"], "result": res,
                "metrics": {"total_score": total, "average_score": total // run["live"] if run["live"] else 0,
                            "top_account": head[0], "top_account_score": head[1]}}
            quality.append(dict(run["quality"], scenario=entry["name"]))
            advice.append({"scenario": entry["name"], "rescued_accounts": run["rescued"], "waived_penalty": run["waived"]})
            keys = sum(len(res[g]) for g in GROUPS)
            load.append({"scenario": entry["name"], "group_keys": keys, "processed_rows": run["processed"],
                         "baseline_row_scans": keys * run["processed"]})
            processed += run["processed"]
        files["data_quality.json"] = {"scenarios": quality}
        files["recommendations.json"] = {"scenarios": advice}
        files["bottleneck_analysis.json"] = {"scenarios": load}
        return {"files": files, "processed_rows_total": processed, "names": [e["name"] for e in manifest["scenarios"]],
                "config": config}
    return _memo("expected", build)


def expected_result(name: str) -> dict[str, Any]:
    def build() -> dict[str, Any]:
        events, rules = extract(name)
        return ref_rate(events, rules)["result"]
    return _memo(f"expected:{name}", build)


# --------------------------------------------------------------------------
# running submitted code
# --------------------------------------------------------------------------


def _root_only_tests_present() -> bool:
    try:
        status = Path("/tests").stat()
    except FileNotFoundError:
        return False
    return status.st_uid == 0 and (status.st_mode & 0o077) == 0


def _grant_read(argument: str) -> None:
    """Make an agent-written path readable before the uid drop.

    Agent editors write through a temp file in the same directory and rename it, so a
    program the agent wrote can land at mode 0600 (owner-only). The checks run that
    program as an unprivileged user, which then cannot open it, and a correct
    submission would score zero for a reason unrelated to the task. Grading runs as
    root, so widening the mode is always allowed here and changes no graded content.
    """
    if not argument.startswith("/app"):
        return
    path = Path(argument)
    if not path.exists():
        return
    try:
        path.chmod(path.stat().st_mode | (0o555 if path.is_dir() else 0o444))
        for parent in path.parents:
            parent.chmod(parent.stat().st_mode | 0o555)
            if str(parent) == "/app":
                break
    except OSError:
        pass


def _untrusted_command(command: list[str]) -> list[str]:
    if os.name == "posix" and os.geteuid() == 0:
        for argument in command:
            _grant_read(argument)
        return [*_SETPRIV, *command]
    if os.name == "posix" and os.geteuid() != 0 and _root_only_tests_present():
        raise RuntimeError("grading must run as root to isolate submitted code from the check files")
    return command


def _snapshot(folder: Path) -> dict[str, str]:
    return {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(folder.iterdir()) if p.is_file()}


def _child(args: list[str], cwd: str, timeout: int, untrusted: bool) -> tuple[str, list[list[str]], int]:
    """Run one child; return stdout, audit lines and the child CPU time in ns."""
    read_fd, write_fd = os.pipe()
    before = resource.getrusage(resource.RUSAGE_CHILDREN)
    command = [sys.executable, "-I", "-S", "-B", *[str(write_fd) if a == "AUDIT_FD" else a for a in args]]
    proc = subprocess.Popen(
        _untrusted_command(command) if untrusted else command,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        text=True,
        env=_CHILD_ENV,
        cwd=cwd,
        start_new_session=True,
        pass_fds=(write_fd,),
    )
    os.close(write_fd)
    chunks: list[bytes] = []
    reader = threading.Thread(target=lambda: chunks.extend(iter(lambda: os.read(read_fd, 65536), b"")), daemon=True)
    reader.start()
    try:
        out, _ = proc.communicate(timeout=timeout)
    finally:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except (ProcessLookupError, PermissionError):
            pass
        proc.wait()
        reader.join(timeout=5)
        os.close(read_fd)
    after = resource.getrusage(resource.RUSAGE_CHILDREN)
    cpu = int(((after.ru_utime - before.ru_utime) + (after.ru_stime - before.ru_stime)) * 1e9)
    audit = []
    for line in b"".join(chunks).decode("utf-8", "replace").splitlines():
        try:
            audit.append(json.loads(line))
        except ValueError:
            continue
    if proc.returncode != 0:
        raise subprocess.CalledProcessError(proc.returncode, args[0])
    return out, audit, cpu


def _submission_run(events: Path, rules: Path, mode: str = "call", cwd: str = "/",
                    record: bool = True) -> tuple[Any, int, str]:
    """Run the submission once on an extract. A recorded run keeps its audit trail for
    the negative checks; the repeat timing runs are not recorded, so the negatives read
    the same memoized runs whatever order the checks run in."""
    folder = rules.parent
    entry = {"extract": str(folder), "events": []}
    try:
        out, audit, cpu = _child(["-c", _RUNNER, "AUDIT_FD", str(SUBMISSION), mode, str(events), str(rules)], cwd,
                                 _MODULE_TIMEOUT, untrusted=True)
        entry["events"] = audit
    finally:
        if record:
            with _LOCK:
                _AUDIT.append(entry)
    return json.loads(out), cpu, out


def _module_run(key: str, events: Path, rules: Path, mode: str, cwd: str) -> tuple[Any, int, str]:
    """One memoized run; a run that fails or times out is remembered as failed, so it
    costs only the checks that read it and is never repeated."""
    def attempt() -> Any:
        try:
            return ("ok", _submission_run(events, rules, mode, cwd))
        except Exception as exc:
            return ("failed", repr(exc))
    status, value = _memo(f"run:{key}:{mode}:{cwd}", attempt)
    if status != "ok":
        raise RuntimeError(value)
    return value


def module_result(key: str, events: Path, rules: Path, mode: str = "call", cwd: str = "/") -> Any:
    return _module_run(key, events, rules, mode, cwd)[0]


def module_text(key: str, events: Path, rules: Path) -> str:
    """The exact text the command line form printed."""
    return _module_run(key, events, rules, "cli", "/")[2]


CLI_EXTRACTS = ("standing", "wide_kinds", "boundary")


def _extract_matches(name: str) -> bool:
    events, rules = extract(name)
    expected = expected_result(name)
    produced = module_result(f"x:{name}", events, rules, "cli" if name in CLI_EXTRACTS else "call")
    return _same(produced, expected)


def _visible_inputs() -> tuple[Path, Path]:
    data = _data_dir()
    return data / "events.csv", data / "rules.json"


# --------------------------------------------------------------------------
# report checks
# --------------------------------------------------------------------------


def _load_report(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def _canonical() -> bool:
    for path in REPORTS:
        raw = path.read_bytes()
        text = raw.decode("ascii")
        parsed = json.loads(text)
        if not isinstance(parsed, dict) or not parsed or text != json.dumps(parsed, indent=2, sort_keys=True) + "\n":
            return False
    return True


def _report_exact(name: str) -> bool:
    """The whole report, in its exact byte form, against the expected object."""
    want = expected_reports()["files"][name]
    raw = (OUT_DIR / name).read_bytes()
    return raw == (json.dumps(want, indent=2, sort_keys=True) + "\n").encode("ascii")


def _whole(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _perf_report() -> bool:
    raw = (OUT_DIR / "perf_report.json").read_bytes().decode("ascii")
    got = json.loads(raw)
    if raw != json.dumps(got, indent=2, sort_keys=True) + "\n":
        return False
    exp = expected_reports()
    if sorted(got) != sorted(PERF_KEYS) or got["ok"] is not True or got["module"] != "/app/out/optimize.py":
        return False
    if not _same(got["scenario_count"], len(exp["names"])) or got["scenarios"] != exp["names"]:
        return False
    if not _same(got["processed_rows_total"], exp["processed_rows_total"]) or not _same(got["relative_target"], 0.7):
        return False
    base, fast = got["baseline_median_ns"], got["optimized_median_ns"]
    if not (_whole(base) and _whole(fast) and base > 0 and fast > 0):
        return False
    if not (_whole(got["warmup_runs"]) and got["warmup_runs"] >= 1 and _whole(got["measured_runs"]) and got["measured_runs"] >= 3):
        return False
    ratio = got["observed_relative_median"]
    if isinstance(ratio, bool) or not isinstance(ratio, (int, float)) or ratio != round(fast / base, 3) or not 0 < ratio <= 0.7:
        return False
    if not isinstance(got["benchmark_method"], str) or not got["benchmark_method"].strip():
        return False
    runs = got["checks_run"]
    return isinstance(runs, list) and bool(runs) and all(isinstance(x, str) and x.strip() for x in runs)


def _interface() -> bool:
    events, rules = _visible_inputs()
    called = module_result("shipped:visible", events, rules, "call")
    printed = module_result("shipped:visible", events, rules, "cli")
    return isinstance(called, dict) and sorted(called) == sorted(RESULT_KEYS) and _same(called, printed)


def _command_line_form() -> bool:
    """The command line prints one object on one line in the stated json.dumps form.

    Only the form is graded here; the values are graded by the report and extract checks."""
    events, rules = _visible_inputs()
    text = module_text("shipped:visible", events, rules)
    if not text.endswith("\n") or text.count("\n") != 1:
        return False
    value = json.loads(text)
    return isinstance(value, dict) and sorted(value) == sorted(RESULT_KEYS) and \
        text == json.dumps(value, sort_keys=True) + "\n"


def _timed_exact_and_fast() -> bool:
    if not _extract_matches("timed"):
        return False
    events, rules = extract("timed")
    source = _baseline_source()

    def base_cost() -> int:
        return _child(["-c", _BASELINE, str(source), str(events), str(rules)], "/", 900, untrusted=False)[2]

    def fast_cost() -> int:
        return _submission_run(events, rules, record=False)[1]

    base_cost()
    fast_cost()
    bases = sorted(base_cost() for _ in range(3))
    fasts = sorted(fast_cost() for _ in range(3))
    return 0 < fasts[1] <= RELATIVE_TARGET * bases[1]


# --------------------------------------------------------------------------
# negative checks
# --------------------------------------------------------------------------


def _ensure_audited_runs() -> None:
    """Make every memoized module run of the checks happen, so the negatives scan the same
    set of runs whatever order the checks run in. A run that fails is skipped."""
    def visible(mode: str) -> None:
        events, rules = _visible_inputs()
        module_result("shipped:visible", events, rules, mode)

    def other(name: str) -> None:
        events, rules = extract(name)
        module_result(f"x:{name}", events, rules, "cli" if name in CLI_EXTRACTS else "call")

    runs = [lambda: visible("call"), lambda: visible("cli")]
    runs += [lambda n=name: other(n) for name in _EXTRACTS]
    runs += [_location_runs]
    for run in runs:
        try:
            run()
        except Exception:
            continue


def _forbidden_open(event: list[str], extract_dir: str) -> bool:
    kind, path, mode = (event + ["", "", ""])[:3]
    if kind not in ("open", "os.listdir", "os.scandir", "os.remove", "os.rename", "os.mkdir", "shutil.rmtree"):
        return False
    if not path or not path.startswith("/"):
        return False
    real = os.path.normpath(path)
    own = str(SUBMISSION.parent)
    if real == extract_dir or real.startswith(extract_dir + "/"):
        return False
    if real == own or real.startswith(own + "/"):
        return real.endswith(".json")
    if any(real == root or real.startswith(root + "/") for root in FORBIDDEN_ROOTS):
        return True
    return real.startswith(("/app/", "/tmp/", "/var/tmp/", "/dev/shm/"))


def _audit_hits(kinds: tuple[str, ...]) -> bool:
    _ensure_audited_runs()
    with _LOCK:
        records = list(_AUDIT)
    for rec in records:
        for event in rec["events"]:
            if "open" in kinds and _forbidden_open(event, rec["extract"]):
                return True
            if "import" in kinds and event[0] == "import" and not (OUT_DIR / f"{event[1]}.py").exists():
                return True
            if "net" in kinds and event[0].startswith("socket."):
                return True
    return False


def _literal_hits() -> int:
    tree = ast.parse(SUBMISSION.read_text(encoding="utf-8"))
    files = expected_reports()["files"]
    graded: set[str] = set()
    for name in SCENARIO_NAMES:
        payload = files[f"scenario_{name}.json"]
        res = payload["result"]
        values = [res["checksum"], payload["metrics"]["total_score"]]
        for group in ("account_totals", "region_totals", "kind_totals"):
            values += list(res[group].values())
        graded |= {str(v) for v in values if abs(v) >= 1000}
    for part in files["data_quality.json"]["scenarios"]:
        graded.add(str(part["cancelled_score"]))
    for part in files["recommendations.json"]["scenarios"]:
        if part["waived_penalty"] >= 1000:
            graded.add(str(part["waived_penalty"]))
    documents = " ".join(_document_texts())
    graded = {g for g in graded if g not in documents}
    seen = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, int) and not isinstance(node.value, bool):
            if str(node.value) in graded:
                seen.add(str(node.value))
        elif isinstance(node, ast.Constant) and isinstance(node.value, str):
            for token in node.value.replace(",", " ").replace(":", " ").split():
                if token.strip("-") in graded:
                    seen.add(token.strip("-"))
    return len(seen)


def _document_texts() -> list[str]:
    data = _data_dir()
    return [p.read_text(encoding="utf-8") for p in sorted(data.glob("*.md"))]


def _hardcoded() -> bool:
    return _literal_hits() >= HARDCODE_THRESHOLD


def _shipped_settings_elsewhere() -> bool:
    """The rerated extract is the shipped visible workload with a rate card and withdrawal
    journal that settle other weights and another cancellation table."""
    if _hardcoded():
        return False
    events, rules = extract("rerated")
    produced = module_result("x:rerated", events, rules, "call")
    stale = ref_rate(events, rules, expected_reports()["config"])["result"]
    return not _same(produced, expected_result("rerated")) and _same(produced, stale)


def _location_runs() -> tuple[Any, Any, Any]:
    events, rules = extract("identity")
    first = module_result("x:identity", events, rules, "call")
    second = _memo("rerun:identity", lambda: _submission_run(events, rules)[0])

    def place() -> Path:
        target = _scratch("moved") / "nested" / "copy"
        shutil.copytree(events.parent, target)
        for p in [target, target.parent, *target.iterdir()]:
            p.chmod(0o755 if p.is_dir() else 0o644)
        return target

    moved = _memo("moved_copy", place)
    elsewhere = _memo("moved:identity", lambda: _submission_run(moved / events.name, moved / rules.name, cwd=str(moved.parent))[0])
    return first, second, elsewhere


def _nondeterministic() -> bool:
    first, second, _ = _location_runs()
    return not _same(first, second)


def _location_dependent() -> bool:
    first, second, elsewhere = _location_runs()
    return _same(first, second) and not _same(first, elsewhere)


